const wrongTeamMessage=c=>'이 방은 '+c.label+' '+c.teamCount+'팀 방이에요. 팀 목록에서 다시 골라 주세요.';
function enterRoom(code,isHost,r,me=null){room=code;host=isHost;pendingResume=null;if(unsub)unsub();unsub=onValue(r,s=>{if(room!==code)return;if(!s.exists()){roomGone('방이 없어졌어요. 방 코드를 확인하고 다시 입장해 주세요.');return}roomData=s.val();applyConfig(roomConfig(roomData));if(!host&&!roomData.members?.[uid]){if(!leavingRoom)roomGone('참가 정보가 없어졌어요. 별명과 나라를 선택해 다시 입장해 주세요.');return}notify('🟢 '+room+' 실시간 연결 중');draw();if(host){processLeavingMembers().catch(e=>notify('나가기 처리 오류: '+e.message));processAttempts().catch(e=>notify('처리 오류: '+e.message));processRollRequests().catch(e=>notify('주사위 처리 오류: '+e.message));processAuthoringRequests().catch(e=>notify('출제중 처리 오류: '+e.message));processCompletedQuestions().catch(e=>notify('출제 완료 처리 오류: '+e.message));processLandmarkProposals().catch(e=>notify('꾸미기 반영 오류: '+e.message));scheduleAutoHandoff();if(roomData.game?.phase==='next'){const key=roomData.game.turnId+':'+roomData.game.team;if(autoNextKey!==key){autoNextKey=key;setTimeout(()=>{if(roomData?.game?.phase==='next'&&roomData.game.turnId+':'+roomData.game.team===key)advanceTurn().catch(e=>notify(e.message))},roomData.game.lastCard?12000:3500)}}}},e=>notify('접속 오류: '+e.message+' · 새로고침하면 같은 기기에서 다시 들어올 수 있어요.'));if(!host&&!me)me={nickname:$('nick').value.trim(),team:+$('team').value};local.set(PROFILE_KEY,JSON.stringify(makeProfile({uid,room,host,...(host?{}:me)})));tabStore.remove('historyRoom');tabStore.remove('historyHost');hideResumeCard();restoreDraft();}
