let leaveProcessing=false;
async function processLeavingMembers(){
 if(leaveProcessing||!host||!roomData)return;leaveProcessing=true;
 try{for(const [id,member] of Object.entries(roomData.members||{})){
  if(id===roomData.hostUid||member.leaving!==true)continue;
  const changes={};
  for(const key of ['rollRequests','authoringRequests','attempts'])changes[key+'/'+id]=null;
  for(const [key,owner] of Object.entries(roomData.nicknames||{}))if(owner===id)changes['nicknames/'+key]=null;
  changes['members/'+id]=null;
  await update(ref(db,'rooms/'+room),changes);
 }}finally{leaveProcessing=false;}
}
