let rollProcessing=false;async function processRollRequests(){if(rollProcessing||!host||!roomData?.rollRequests)return;const d=roomData,g=d.game;const entries=Object.entries(d.rollRequests);const valid=entries.find(([id,v])=>v.turnId===g.turnId&&(g.phase==='roll'?id===player(d,g):g.phase==='order'&&orderCanRoll(d,g,id)));if(!valid)return;rollProcessing=true;try{const [id,v]=valid;await remove(ref(db,'rooms/'+room+'/rollRequests/'+id));await doRoll(true)}finally{rollProcessing=false}}
