async function doRoll(fromRequest){const d=roomData,g=d?.game;if(!d||!g||g.phase==='finished')return;if(!host){if(!(g.phase==='roll'&&player(d,g)===uid||g.phase==='order'&&orderCanRoll(d,g,uid)))return;if(pendingRollKey===rollStateKey(g))return;if(offline())return;pendingRollKey=rollStateKey(g);drawRollAttention(d,g);try{await set(ref(db,'rooms/'+room+'/rollRequests/'+uid),{turnId:g.turnId,team:Number(d.members?.[uid]?.team),requestedAt:Date.now()});notify('🎲 주사위 요청을 보냈습니다. 교사 화면에서 처리 중입니다.')}catch(e){pendingRollKey='';draw();alert('주사위 요청 오류: '+e.message)}return}if(g.phase==='order'){if(!host&&!orderCanRoll(d,g,uid))return;await update(ref(db,'rooms/'+room+'/game'),orderRollPatch(g,twoDice(),ctx(),Date.now()));return}
if(g.phase!=='roll'||!canAct(d,g))return;const mover=player(d,g),pieces=studentPieces(d,g);if(!mover)return notify('이 나라에 입장한 학생이 없습니다. 교사가 다음 팀으로 넘겨 주세요.');const studentTokens={...(g.studentTokens||{})};for(const p of pieces)studentTokens[p.id]={team:p.team,position:p.position};const pair=twoDice(),steps=pair[0]+pair[1],bonusRoll=pair[0]===pair[1],positions=Array.from({length:TEAMS},(_,i)=>Number(g.positions?.[i]||0)),old=studentTokens[mover].position,absolute=old+steps,next=absolute%spaces.length,laps=Array.from({length:TEAMS},(_,i)=>Number(g.laps?.[i]||0));if(absolute>=spaces.length)laps[g.team]++;positions[g.team]=next;studentTokens[mover]={team:g.team,position:next};const sp=spaces[next];let lastCard=null;const cardPoints={...(g.cardPoints||{})},decks=eraCards||HISTORY_CARDS;if(decks[sp.kind]){const deck=decks[sp.kind],card=deck[Math.floor(Math.random()*deck.length)];lastCard={kind:sp.kind,title:card[0],text:card[1],points:card[2],team:g.team};cardPoints[g.team]=Number(cardPoints[g.team]||0)+card[2]}const target=sp.kind==='property'?sp.id:null,owner=target===null?-1:Number(g.owners?.[target]??-1),claim=target===null?null:d.pendingClaims?.[target],phase=claim?(Number(claim.team)===Number(g.team)?'author':'wait'):target===null||owner===g.team?'next':owner<0?'author':'quiz',turnId=(g.turnId||0)+1;if(target!==null&&owner<0&&!pendingClaim(d,target)){await set(ref(db,'rooms/'+room+'/pendingClaims/'+target),{topic:target,team:g.team,turnId,createdAt:Date.now()})}await update(ref(db,'rooms/'+room+'/game'),{positions,studentTokens,laps,turnId,lastCard,cardPoints,lastRoll:steps,lastDice:pair,rollStartedAt:Date.now(),bonusRoll,questionId:target,phase,message:phase==='wait'?'⏳ '+tn(Number(claim.team))+'이(가) 거점 '+(target+1)+' 문제를 출제 중이에요. 곧 다음 차례로 넘어가요.':lastCard?'📜 '+names[g.team]+' · '+lastCard.title+' · 국력 '+(lastCard.points>0?'+':'')+lastCard.points+'점':target!==null&&owner<0?'📝 거점 '+(target+1)+'에 도착! 문제를 만드는 동안 다음 팀이 자동으로 주사위를 굴려요.':phase==='quiz'?'상대 나라 영토입니다. 문제를 풀어 재점령에 도전하세요.':names[g.team]+' 팀 '+steps+'칸 이동! 다음 차례로 넘어갑니다.'});}
