async function submitAnswer(choice){const g=roomData?.game;if(answerSubmitting||!g||g.phase!=='quiz'||(!host&&!isTeamMember(roomData,g)))return;const passed=choice===null;if(!passed&&(!Number.isInteger(choice)||choice<0||choice>3))return;const previous=roomData.attempts?.[uid];if(previous?.turnId===g.turnId)return;if(offline())return;answerSubmitting=true;try{await set(ref(db,`rooms/${room}/attempts/${uid}`),{turnId:g.turnId,choice:passed?0:choice,passed,team:g.team,submittedAt:Date.now(),nickname:roomData.members?.[uid]?.nickname||'참가자'});notify(passed?'🤷 모름·패스로 제출했습니다. 다른 팀원은 계속 풀 수 있어요.':'답안을 제출했습니다. 결과를 기다립니다.')}catch(e){alert('제출 실패: '+e.message)}finally{answerSubmitting=false}}
async function processAttempts(){if(processing||!host||!roomData?.attempts||roomData.game?.phase!=='quiz')return;processing=true;try{let g=roomData.game;let attempts=Object.entries(roomData.attempts).filter(([id,v])=>v.turnId===g.turnId&&v.team===g.team&&Number(roomData.members?.[id]?.team)===g.team).sort((a,b)=>(a[1].submittedAt||0)-(b[1].submittedAt||0));if(!attempts.length)return;let [who,a]=attempts[0],id=g.questionId,q=roomData.questions?.[id]||fallbackQuestion(id);if(!q)return;const winning=attempts.find(([_,v])=>v.passed!==true&&v.choice===q.answer);if(!winning&&attempts.length<roster(roomData,g.team).length)return;const correct=!!winning,chosen=winning?.[1]||a;const priorOwner=Number(g.owners?.[id]??-1);let msg=correct?`✅ ${chosen.nickname} 정답! ${tn(g.team)}이(가) ${q.name||'거점 '+(Number(id)+1)} 거점을 확보했습니다. ${q.explain}`:`❌ 모두 오답 또는 패스! 정답: ${q.options[q.answer]}. ${q.explain}`;let result=await runTransaction(ref(db,'rooms/'+room+'/game'),old=>{if(!old||old.phase!=='quiz'||old.turnId!==g.turnId)return;const owners=[...old.owners],decorationVersions={...(old.decorationVersions||{})};if(correct){owners[id]=old.team;if(Number(old.owners[id])!==Number(old.team))decorationVersions[id]=Number(decorationVersions[id]||0)+1}const skipTurns={...(old.skipTurns||{})};if(!correct)skipTurns[old.team]=Number(skipTurns[old.team]||0)+1;return {...old,owners,decorationVersions,skipTurns,bonusRoll:correct?old.bonusRoll:false,phase:'next',message:msg+(correct?'':' 거점 획득 실패 · 다음 자기 차례 1회 쉬기.')}},{applyLocally:false});if(result.committed){if(correct&&priorOwner!==g.team)await remove(ref(db,'rooms/'+room+'/landmarks/'+id)).catch(()=>{});await remove(ref(db,'rooms/'+room+'/attempts'));}}finally{processing=false}}
$('submit').onclick=async()=>{if(!roomData)return;let id=+$('topic').value,opts=$('opts').value.split('\n').map(s=>s.trim()).filter(Boolean),q=$('q').value.trim(),explain=$('explain').value.trim();if(!Number.isInteger(id)||id<0||id>=24)return alert('올바른 거점을 선택하세요.');if(!q||opts.length!==4||!explain)return alert('문제, 보기 4개, 해설을 모두 입력하세요.');if(q.length>200||opts.some(s=>s.length>100)||explain.length>300)return alert('문제 또는 보기가 너무 깁니다.');const g=roomData.game,claim=roomData.pendingClaims?.[id],isClaim=!!claim&&Number(claim.team)===Number(roomData.members?.[uid]?.team);if(!isClaim)return alert('우리 팀의 출제 대기 거점을 선택해 주세요.');if(g.phase==='finished')return alert('게임이 종료되었습니다.');if(offline())return;try{await set(ref(db,'rooms/'+room+'/completedQuestions/'+id),{authorUid:uid,author:roomData.members?.[uid]?.nickname||'참가자',topic:id,q,options:opts,answer:+$('answer').value-1,explain,claimTurnId:claim.turnId,claimTeam:claim.team,createdAt:Date.now()});$('q').value='';$('opts').value='';$('explain').value='';saveDraft();notify('✅ 출제 완료! 자동 승인 및 점령을 처리하고 있습니다.')}catch(e){alert('출제 완료 오류: '+e.message)}};
