async function processLandmarkProposals(){if(landmarkProcessing||!host||!roomData?.landmarkProposals)return;landmarkProcessing=true;const handled=new Set();let failed=false;try{for(const [key,p] of Object.entries(roomData.landmarkProposals||{})){const d=roomData,g=d.game,topic=Number(p.topic),team=Number(p.ownerTeam??d.members?.[p.authorUid]?.team??-1),version=Number(p.territoryVersion||0),image=safeImage(p.imageUrl||'');const valid=g.phase!=='finished'&&Number.isInteger(topic)&&topic>=0&&topic<24&&isTeamIndex(team,cfg)&&Number(g.owners?.[topic])===team&&version===Number(g.decorationVersions?.[topic]||0)&&(p.authorUid===d.hostUid||Number(d.members?.[p.authorUid]?.team)===team)&&typeof p.name==='string'&&p.name.trim().length>0&&p.name.length<=24&&(!p.imageUrl||!!image);if(valid){await set(ref(db,'rooms/'+room+'/landmarks/'+topic),{name:p.name.trim(),imageUrl:image,ownerTeam:team,version});}await remove(ref(db,'rooms/'+room+'/landmarkProposals/'+key));handled.add(key);}}catch(e){failed=true;throw e}finally{landmarkProcessing=false;if(!failed&&Object.keys(roomData?.landmarkProposals||{}).some(key=>!handled.has(key)))setTimeout(()=>processLandmarkProposals().catch(e=>notify(e.message)),100)}}
